CREATE OR REPLACE FUNCTION public.validate_family_checkin() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p public.patients%ROWTYPE; idx integer; item jsonb; BEGIN SELECT * INTO p FROM public.patients WHERE id=NEW.patient_id FOR SHARE; IF p.ai_plan IS NULL OR (p.cognitive_risk IN ('中风险','高风险') AND (p.ai_plan_confirmed_at IS NULL OR p.ai_plan_confirmed_at<p.ai_plan_at)) THEN RAISE EXCEPTION '请等待医生确认方案'; END IF; IF (p.ai_plan_at IS NULL AND NEW.plan_version<>'initial') OR (p.ai_plan_at IS NOT NULL AND NEW.plan_version::timestamptz IS DISTINCT FROM p.ai_plan_at) THEN RAISE EXCEPTION '方案已更新，请重新打开任务'; END IF; IF NEW.task_key ~ '^training-[0-9]+$' THEN idx=substring(NEW.task_key from '[0-9]+$')::integer; item=p.ai_plan->'training'->idx; IF item IS NULL OR NEW.category<>'训练' OR item->>'setting' IS NULL OR item->>'setting' NOT IN ('家庭作业','家庭任务','居家','家庭') OR NEW.title IS DISTINCT FROM (item->>'activity') THEN RAISE EXCEPTION '训练任务必须来自已确认的家庭训练方案'; END IF; ELSE IF NEW.task_key !~ '^intervention-[0-9]+-[0-9]+$' THEN RAISE EXCEPTION '任务不存在'; END IF; item=p.ai_plan->'interventions'->(split_part(NEW.task_key,'-',2)::integer); IF item IS NULL OR item->>'category' IS NULL OR item->>'category' NOT IN ('营养','睡眠') OR NEW.category IS DISTINCT FROM item->>'category' OR NEW.title IS DISTINCT FROM (item->'actions'->>(split_part(NEW.task_key,'-',3)::integer)) THEN RAISE EXCEPTION '任务必须来自已确认的营养或睡眠方案'; END IF; END IF; RETURN NEW; END $$;